/**
 * Minutos de lectura estimados a partir del texto real del artículo, a 200
 * palabras por minuto. Se calcula en lugar de fijarse a mano para que no se
 * desincronice al editar un artículo.
 */
const WORDS_PER_MINUTE = 200;

function countWords(sections: ArticleSection[]): number {
  return sections.reduce((total, section) => {
    const text = [section.text ?? "", ...(section.items ?? [])].join(" ");
    return total + text.split(/\s+/).filter(Boolean).length;
  }, 0);
}

export function getReadTime(article: Article, locale: "es" | "en"): number {
  const sections = locale === "en" ? article.enSections : article.sections;
  return Math.max(1, Math.round(countWords(sections) / WORDS_PER_MINUTE));
}
